33	    enabled: open && requisicaoId > 0,
34	    queryFn: async () => {
35	      // 1. Fetch events
36	      const { data: eventos, error: eventosError } = await (supabase.from('etiquetas_qr_eventos') as any)
37	        .select('etiqueta_uid, usuario_nome, metadata, created_at')
38	        .eq('tipo_evento', 'saida_requisicao')
39	        .eq('referencia_tipo', 'requisicao')
40	        .eq('referencia_id', String(requisicaoId));
41	
42	      if (eventosError) throw eventosError;
43	
44	      if (!eventos || eventos.length === 0) {
45	        return [];
46	      }
47	
48	      const uids = [...new Set(eventos.map((e: any) => e.etiqueta_uid as string))];
49	
50	      // 2. Fetch tags
51	      const { data: tags, error: tagsError } = await (supabase.from('etiquetas_qr') as any)
52	        .select('uid, produto_nome_snapshot')
53	        .in('uid', uids);
54	
55	      if (tagsError) throw tagsError;
56	
57	      const tagsMap = new Map<string, string | null>(
58	        (tags || []).map((t: any) => [t.uid as string, t.produto_nome_snapshot as string | null])
59	      );
60	
61	      // 3. Join
62	      return eventos.map((e: any) => ({
63	        etiqueta_uid: e.etiqueta_uid as string,
64	        usuario_nome: e.usuario_nome as string | null,
65	        metadata: (e.metadata || {}) as SaidaItem['metadata'],
66	        created_at: e.created_at as string,
67	        produto_nome_snapshot: tagsMap.get(e.etiqueta_uid as string) ?? null,
68	      })) as SaidaItem[];
69	    }
70	  });
