107	            <div className="space-y-4">
108	              {/* Summary Bar */}
109	              <div className="flex items-center gap-4 p-4 rounded-xl bg-[#57715B]/5 border border-[#57715B]/10">
110	                <div>
111	                  <div className="text-xs font-medium text-muted-foreground uppercase tracking-wider">Total de Itens</div>
112	                  <div className="text-lg font-bold text-[#2D362E] dark:text-[#E6DCCF]">{totalItens}</div>
113	                </div>
114	                <div className="w-px h-8 bg-[#57715B]/10" />
115	                <div>
