117	                  <div className="text-lg font-bold text-[#57715B]">{totalQuantidade}</div>
118	                </div>
119	              </div>
120	
121	              {/* Table */}
122	              <div className="rounded-xl border border-[#57715B]/10 overflow-hidden">
123	                <div className="overflow-x-auto">
124	                  <Table>
125	                    <TableHeader className="bg-[#57715B]/5 border-b border-[#57715B]/10">
126	                      <TableRow className="hover:bg-transparent">
127	                        <TableHead className="font-semibold text-[#57715B]">Produto</TableHead>
128	                        <TableHead className="font-semibold text-[#57715B]">Lote</TableHead>
129	                        <TableHead className="font-semibold text-[#57715B] text-center">Qtd</TableHead>
130	                        <TableHead className="font-semibold text-[#57715B]">Operador</TableHead>
131	                        <TableHead className="font-semibold text-[#57715B] text-right">Horário</TableHead>
132	                      </TableRow>
133	                    </TableHeader>
134	                    <TableBody>
135	                      {itens.map((item, idx) => (
136	                        <TableRow
137	                          key={`${item.etiqueta_uid}-${idx}`}
138	                          className="hover:bg-[#57715B]/5 border-b border-[#57715B]/5 last:border-0 transition-colors"
139	                        >
