144	                            {item.metadata?.lote_id ? (
145	                              <span className="font-mono text-xs text-muted-foreground bg-white/50 dark:bg-black/20 px-2 py-1 rounded-lg border border-[#57715B]/10">
146	                                {item.metadata.lote_id.substring(0, 8)}
147	                              </span>
148	                            ) : (
149	                              <span className="text-xs text-muted-foreground italic">N/A</span>
150	                            )}
151	                          </TableCell>
152	                          <TableCell className="text-center font-bold text-[#2D362E] dark:text-[#E6DCCF]">
153	                            {item.metadata?.quantidade ?? 0}
154	                          </TableCell>
155	                          <TableCell className="text-sm text-muted-foreground">
156	                            {item.usuario_nome || 'Desconhecido'}
157	                          </TableCell>
158	                          <TableCell className="text-right font-mono text-xs text-muted-foreground">
159	                            {format(new Date(item.created_at), 'dd/MM HH:mm', { locale: ptBR })}
160	                          </TableCell>
161	                        </TableRow>
162	                      ))}
163	                    </TableBody>
164	                  </Table>
165	                </div>
166	              </div>
167	            </div>
168	          )}
169	        </div>
170	
171	        <div className="p-4 border-t border-[#57715B]/10 flex justify-end bg-white/50 dark:bg-black/20">
172	          <Button variant="ghost" onClick={onClose} className="text-[#57715B] hover:bg-[#57715B]/10">
173	            Fechar
174	          </Button>
175	        </div>
176	      </DialogContent>
177	    </Dialog>
178	  );
179	}
