if(\$t -match '^sbp_'){ Write-Output ('OK:'+\$t.Length); Set-Content -Path \$env:TEMP\sbp.txt -Value \$t -NoNewline -Encoding ascii } else { Write-Output ('BAD:'+\$t.Substring(0,[Math]::Min(12,\$t.Length))) }
" 2>&1 | tail -3
